solutions.naive:
class Solution:
    def minFallingPathSum(self, grid: list[list[int]]) -> int:
        n = len(grid)
        if n == 1:
            return grid[0][0]
        dp = [row[:] for row in grid]
        for r in range(1, n):
            for c in range(n):
                dp[r][c] += min(dp[r - 1][pc] for pc in range(n) if pc != c)
        return min(dp[-1])

