class Solution:
    def minFallingPathSum(self, grid: list[list[int]]) -> int:
        n = len(grid)
        prev = grid[0][:]
        for r in range(1, n):
            first = second = 10 ** 18
            idx = -1
            for c, v in enumerate(prev):
                if v < first:
                    second, first, idx = first, v, c
                elif v < second:
                    second = v
            prev = [grid[r][c] + (second if c == idx else first) for c in range(n)]
        return min(prev)

