class Solution:
    def minFallingPathSum(self, grid: list[list[int]]) -> int:
        best1 = best2 = 0
        best_col = -1
        for row in grid:
            nb1 = nb2 = 10 ** 18
            nb_col = -1
            for c, x in enumerate(row):
                v = x + (best2 if c == best_col else best1)
                if v < nb1:
                    nb2, nb1, nb_col = nb1, v, c
                elif v < nb2:
                    nb2 = v
            best1, best2, best_col = nb1, nb2, nb_col
        return best1

